import{j as e}from"./vendor-react-BlVc7RbY.js";import{P as a}from"./ProblemPage-DPRIC8QV.js";import"./vendor-misc-BAGPFqjl.js";import"./index-eowHmnw-.js";import"./vendor-ui-D7glRu94.js";import"./vendor-framer-motion-_M9ViFvP.js";import"./Breadcrumb-H_CkWXx7.js";function d(){return e.jsx(a,{slug:"humidade-nas-paredes",pageTitle:"Humidade nas Paredes: Causas, Sinais e Solução Sem Obras",metaTitle:"Humidade nas Paredes: Solução Sem Obras | Evoluimos Comércio",metaDescription:"Humidade ascendente, condensação e salitre nas paredes. Identifique as causas e elimine o problema com Drymat, sem obras e com 80 a 100% de redução em 2 a 6 meses.",heroImage:"/semhumidade.png",heroImageAlt:"Parede de casa portuguesa com humidade ascendente eliminada",introParagraph:"Manchas escuras, tinta a descascar, salitre, cheiro a bolor. Se a sua casa tem estes sinais, o problema é humidade nas paredes. A boa notícia: hoje é possível tratar sem demolir.",searchKeywords:["humidade nas paredes","humidade ascendente","paredes com salitre","casa húmida solução","eliminar humidade sem obras"],problem:"A humidade nas paredes é um dos problemas estruturais mais comuns em Portugal, especialmente em casas antigas, edifícios à beira-mar e habitações no piso térreo. A água acumula-se no interior do reboco, deteriora a pintura, fragiliza a alvenaria e cria um ambiente propício a bolores e ácaros. Para além do impacto visual, agrava alergias, asma e problemas respiratórios.",causes:[{title:"Humidade ascendente",text:"Água do solo que sobe pelas paredes por capilaridade. Aparece nos primeiros 1,5 metros das paredes exteriores e divisórias. É o tipo mais frequente em edifícios anteriores aos anos 80, sem barreira anti-capilar funcional."},{title:"Condensação interior",text:"Vapor de água do ambiente que condensa em superfícies frias. Surge tipicamente em cantos, tetos, atrás de móveis encostados a paredes exteriores e em zonas pouco ventiladas como casas de banho e cozinhas."},{title:"Infiltrações pelo exterior",text:"Água da chuva que entra por fissuras na fachada, juntas de janelas, telhados em mau estado ou caleiras entupidas. Cria manchas localizadas que crescem em períodos de chuva intensa."},{title:"Salinidade junto ao mar",text:"Em zonas costeiras, a maresia transporta sais que cristalizam nas paredes (salitre). Estes sais retêm humidade do ar e aceleram a degradação do reboco, mesmo em construções recentes."}],consequences:["Degradação da pintura, do reboco e da alvenaria, com custos crescentes de reparação","Bolores e ácaros que pioram alergias, asma e problemas respiratórios em crianças e idosos","Cheiro persistente a bolor que se impregna em móveis, roupas e cortinas","Perda de eficiência energética, paredes húmidas isolam pior e aumentam custos de aquecimento entre 20 e 30%","Desvalorização do imóvel à venda ou para arrendamento","Em casos avançados, comprometimento estrutural e necessidade de obras profundas"],solution:"A solução começa por identificar corretamente o tipo de humidade. Para humidade ascendente trabalhamos com o sistema austríaco Drymat, que inverte o movimento capilar da água através de frequência eletromagnética. Não exige demolições, injecções químicas ou perfurações na parede. Para condensação e regulação do ar interior aplicamos o revestimento cerâmico ClimateCoating, que isola termicamente e mantém a humidade do ar próxima dos 55%. Para infiltrações exteriores aplicamos o ClimateCoating ThermoProtect na fachada, criando uma membrana impermeável e respirável.",benefits:["80 a 100% de redução da humidade nas paredes em 2 a 6 meses","Instalação em poucas horas, sem obras pesadas","Sem injecções químicas e sem demolição","Compatível com edifícios históricos e em reabilitação","Garantia de 10 anos no sistema Drymat","Eficiência energética melhorada após a parede secar"],process:[{title:"Diagnóstico gratuito",text:"Visita técnica ao imóvel com medição de humidade nas paredes. Identificamos o tipo de problema e apresentamos um plano e orçamento personalizado, sem compromisso."},{title:"Instalação do Drymat",text:"O equipamento é fixado a uma parede interior e ligado à corrente. Não há fios espalhados pelas divisões nem perfurações estruturais. Demora poucas horas."},{title:"Secagem progressiva",text:"Durante 2 a 6 meses, o Drymat inverte a capilaridade. A água deixa de subir e a parede vai secando. Acompanhamos com medições periódicas."},{title:"Aplicação de ClimateCoating",text:"Com a parede seca, aplicamos o revestimento cerâmico como uma tinta interior. Regula a humidade do ar e reforça o isolamento térmico."},{title:"Acompanhamento e garantia",text:"Drymat com garantia de 10 anos e ClimateCoating com garantia superior a 15 anos. Se o problema voltar, voltamos."}],faqs:[{question:"Como sei se tenho humidade ascendente ou apenas condensação?",answer:"A humidade ascendente aparece sempre na zona inferior das paredes, até cerca de 1,5 metros de altura, com manchas horizontais, salitre branco e tinta a descascar. A condensação aparece em cantos, tetos, atrás de móveis e perto de janelas, normalmente em zonas pouco ventiladas, e melhora temporariamente com ventilação."},{question:"O Drymat funciona em qualquer tipo de parede?",answer:"Sim. O sistema é compatível com paredes em pedra, tijolo, betão, taipa, adobe e alvenarias mistas. É especialmente eficaz em construções antigas onde não existe barreira anti-capilar."},{question:"Demora quanto tempo a ver resultados visíveis?",answer:"Os primeiros sinais de melhoria aparecem entre 2 e 4 meses após a instalação. A secagem completa ocorre tipicamente entre 4 e 6 meses, dependendo da espessura da parede, do tipo de reboco e da intensidade do problema inicial."},{question:"É preciso retirar os móveis ou sair de casa durante a instalação?",answer:"Não. A instalação é não invasiva e demora apenas algumas horas. Pode continuar a viver normalmente na casa durante todo o processo de secagem."},{question:"O sistema consome muita eletricidade?",answer:"O Drymat consome menos do que uma lâmpada LED, cerca de 0,5 a 1 watt. O custo mensal de eletricidade é praticamente imperceptível na fatura."},{question:"Funciona em apartamentos?",answer:"Sim. O Drymat foi instalado em vários apartamentos em Lisboa, Porto, Faro e Tavira. Trata as paredes do apartamento independentemente dos pisos superiores ou inferiores."},{question:"O salitre desaparece sem ser raspado?",answer:"O salitre é um sintoma da humidade. Após o tratamento, o salitre deixa de aparecer e o que existia desaparece naturalmente em poucos meses com a secagem da parede. Não exige raspagem agressiva nem produtos químicos."},{question:"Atendem em todo o Portugal?",answer:"Sim. Estamos sediados no Algarve mas fazemos visitas e instalações em todo o Portugal continental, Madeira e Açores. Resposta inicial entre 24 e 72 horas após contacto."}],relatedProducts:[{label:"Drymat Anti-Humidade",path:"/products/drymat"},{label:"ClimateCoating",path:"/products/climatecoating"}],relatedSolutions:[{label:"Eliminar humidade nas paredes",path:"/solutions/eliminate-moisture"},{label:"Isolamento térmico",path:"/isolamento-termico"},{label:"Reduzir custos de aquecimento",path:"/reduzir-custos-aquecimento"}],serviceName:"Tratamento de humidade nas paredes sem obras",serviceType:"Tratamento de humidade ascendente, condensação e infiltrações"})}export{d as default};
